msg.payload = {event:'heartbeat', level:'info', message:'Node-RED runtime heartbeat', flow_name:'SFT - Monitor FastAPI', timestamp:Date.now()/1000};
msg.url = env.get('SFT_MONITOR_URL') || 'http://127.0.0.1:8000/api/v1/node-red/events';
msg.headers = {'Content-Type':'application/json','X-Node-RED-Token':env.get('SFT_MONITOR_TOKEN') || ''};
return msg;

const s = msg.status || {};
msg.payload = {event:'node_status', level:'info', node_id:s.source && s.source.id || '', node_type:s.source && s.source.type || '', node_name:s.source && s.source.name || '', message:s.text || s.fill || 'Node status changed', timestamp:Date.now()/1000};
msg.url = env.get('SFT_MONITOR_URL') || 'http://127.0.0.1:8000/api/v1/node-red/events';
msg.headers = {'Content-Type':'application/json','X-Node-RED-Token':env.get('SFT_MONITOR_TOKEN') || ''};
return msg;

const e = msg.error || {};
msg.payload = {event:'node_error', level:'error', node_id:e.source && e.source.id || '', node_type:e.source && e.source.type || '', node_name:e.source && e.source.name || '', message:e.message || 'Node-RED node error', timestamp:Date.now()/1000};
msg.url = env.get('SFT_MONITOR_URL') || 'http://127.0.0.1:8000/api/v1/node-red/events';
msg.headers = {'Content-Type':'application/json','X-Node-RED-Token':env.get('SFT_MONITOR_TOKEN') || ''};
return msg;
